CREATE TABLE `supervisi_pra` (
  `id` int NOT NULL AUTO_INCREMENT,
  `guru_id` int NOT NULL,
  `materi_topik` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tujuan_pembelajaran` text COLLATE utf8mb4_unicode_ci,
  `tanggal_telaah` date DEFAULT NULL,
  `rpp_scores` longtext COLLATE utf8mb4_unicode_ci,
  `bk_scores` longtext COLLATE utf8mb4_unicode_ci,
  `bk_dl_scores` longtext COLLATE utf8mb4_unicode_ci,
  `bk_dl_notes` longtext COLLATE utf8mb4_unicode_ci,
  `pra_feedback` longtext COLLATE utf8mb4_unicode_ci,
  `catatan_pra` text COLLATE utf8mb4_unicode_ci,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `guru_id` (`guru_id`),
  CONSTRAINT `supervisi_pra_ibfk_1` FOREIGN KEY (`guru_id`) REFERENCES `guru` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
